// UUID v7 fonksiyonu
const v7 = () => {
  return 'tttttttt-tttt-7xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c){
    const r = Math.trunc(Math.random() * 16);
    const v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  }).replace(/[t]{8}-[t]{4}/, function (){
    const unixtimestamp = Date.now().toString(16).padStart(12, '0');
    return unixtimestamp.slice(0, 8) + '-' + unixtimestamp.slice(8);
  });
}

// Ana workflow'dan gelen veriyi al
const inputDataRaw = $input.all();
if (!inputDataRaw || !inputDataRaw.length) {
  return []; // input boşsa boş array dön
}

const inputData = inputDataRaw[0].json;

// Eğer data bir array değilse array yap
let data;
if (Array.isArray(inputData)) {
  data = inputData;
} else if (inputData.query) {
  try {
    data = JSON.parse(inputData.query);
    if (!Array.isArray(data)) data = [data]; // parse sonrası array değilse array yap
  } catch (e) {
    data = []; // parse hatalıysa boş array
  }
} else if (typeof inputData === 'object' && inputData !== null) {
  data = [inputData]; // tek obje ise array'e çevir
} else {
  data = []; // diğer durumlarda boş array
}

// Her item'a UUID ekle ve güvenli şekilde alanları doldur
const dataWithId = data.map(i => {
  i = i || {}; // undefined ise boş obje
  const uuid = v7();
  return { 
    UUID: uuid, 
    Name: i.Name || i.name || '',
    Address: i.Address || i.address || '',
    Number: i.Number || i.number || '',
    Website: i.Website || i.website || '',
    Rating: i.Rating || i.rating || '',
    "Opening Hours": i["Opening Hours"] || i.opening_hours || '',
    Email: i.Email || i.email || 'N/A'
  };
});

return dataWithId;
